query:
query dashboardBoxStats {
  viewer {
    id
    ... on Member {
      players {
        id
        matchesPlayed
        matchesWon
        __typename
        alias {
          id
          stats {
            skillLevel
            __typename
          }
          __typename
        }
        session {
          id
          description
          year
          name
          __typename
        }
        league {
          id
          name
          slug
          __typename
        }
      }
      __typename
    }
    __typename
  }
}
